class Resource extends Base {
 mount(){this.items??=[{id:'project',label:'fieldwork',children:[{id:'readme',label:'README.md',content:'# Fieldwork\n\nA little room for an idea.\n\nStart with the useful part.\nKeep the details considered.'},{id:'src',label:'src',children:[{id:'components',label:'components',children:[{id:'hero',label:'Hero.html',content:'<section class="hero">\n  <p>Independent by design.</p>\n  <h1>Something worth making.</h1>\n</section>'},{id:'navigation',label:'Navigation.js',content:'const links = [\n  { label: "Work", href: "#work" },\n  { label: "About", href: "#about" }\n];'}]},{id:'styles',label:'styles.css',content:':root {\n  --ink: #24392c;\n  --paper: #f7f5ee;\n}\n\nmain { max-width: 72rem; }'}]},{id:'assets',label:'assets',children:[{id:'colors',label:'palette.json',content:'{\n  "moss": "#a4bb94",\n  "clay": "#c7a78b",\n  "ink": "#24392c"\n}'}]}]}];this.opened=new Set(['project','src','components']);this.focusId=this.items[0]?.id;this.selected='readme';this.render(`<section class="workspace panel"><header class="row between"><div><span class="label">EVERYTHING HAS A PLACE</span><h2>A map of the work.</h2></div><span class="tag">PROJECT EXPLORER</span></header><div class="body"><nav role="tree" aria-label="Project files"></nav><main><div class="doc-head"><span data-name>README.md</span><small>READ-ONLY PREVIEW</small></div><pre tabindex="0"><code></code></pre><div class="doc-foot"><span>UTF-8</span><span data-size></span></div></main></div></section>`,`.workspace{padding:26px;background:var(--bg);min-height:470px}h2{font:400 clamp(25px,4vw,34px) Georgia;margin-top:10px}.tag{font-size:7px;letter-spacing:1px;color:var(--muted);border:1px solid var(--line);border-radius:5px;padding:6px 8px}.body{display:grid;grid-template-columns:minmax(170px,.9fr) minmax(0,1.7fr);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-top:26px;min-height:315px}nav{padding:17px 10px;background:var(--panel);border-right:1px solid var(--line)}[role=treeitem]{padding:9px 7px 9px calc(7px + var(--depth)*13px);cursor:pointer;display:flex;align-items:center;gap:8px;border-radius:5px;font-size:11px;color:var(--muted);min-height:35px}[role=treeitem][aria-selected=true]{background:#c6e6b010;color:var(--accent)}[role=treeitem]:hover{background:#ffffff04}.symbol{display:inline-block;min-width:14px;color:#a9bd96}.doc-head,.doc-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px;font:11px ui-monospace}.doc-head{border-bottom:1px solid var(--line)}.doc-head small{font:6px system-ui;letter-spacing:1px;color:var(--muted)}main{min-width:0;display:flex;flex-direction:column}pre{padding:20px 17px;margin:0;overflow:auto;white-space:pre-wrap;word-break:break-word;font:11px/2 ui-monospace;color:var(--accent);flex:1;max-height:300px}.doc-foot{padding:11px 17px;font-size:8px;border-top:1px solid var(--line);color:var(--muted)}:host([density=compact]) [role=treeitem]{padding-top:5px;padding-bottom:5px;min-height:29px}@media(max-width:480px){.workspace{padding:22px 15px}.body{grid-template-columns:1fr}nav{border-right:0;border-bottom:1px solid var(--line);max-height:260px;overflow-y:auto}main{min-height:250px}.tag{display:none}}`);this.listen(this.$('nav'),'click',e=>{const item=e.target.closest('[data-id]');if(item)this.activate(item.dataset.id);});this.listen(this.$('nav'),'keydown',e=>this.key(e));this.draw();this.select('readme');}
 flatten(nodes=this.items,parent=null,depth=0,all=false){return nodes.flatMap(node=>[{...node,parent,depth},...((all||this.opened.has(node.id))&&node.children?this.flatten(node.children,node.id,depth+1,all):[])]);}
 draw(){const make=(nodes,depth=0)=>nodes.map(node=>`<div role="none"><div role="treeitem" data-id="${escape(node.id)}" tabindex="${node.id===this.focusId?0:-1}" aria-level="${depth+1}" aria-selected="${node.id===this.selected}" ${node.children?`aria-expanded="${this.opened.has(node.id)}"`:''} style="--depth:${depth}"><span class="symbol" aria-hidden="true">${node.children?(this.opened.has(node.id)?'⌄':'›'):'◇'}</span><span>${escape(node.label)}</span></div>${node.children&&this.opened.has(node.id)?`<div role="group">${make(node.children,depth+1)}</div>`:''}</div>`).join('');this.$('nav').innerHTML=make(this.items);}
 focus(id){this.focusId=id;this.$$('[role=treeitem]').forEach(n=>n.tabIndex=n.dataset.id===id?0:-1);this.$(`[data-id="${CSS.escape(id)}"]`)?.focus();}
 activate(id){const item=this.flatten(this.items,null,0,true).find(n=>n.id===id);if(!item)return;this.focusId=id;if(item.children){this.opened.has(id)?this.opened.delete(id):this.opened.add(id);this.draw();this.focus(id);}else this.select(id);}
 select(id){const item=this.flatten(this.items,null,0,true).find(n=>n.id===id);if(!item||item.children)return;this.focusId=id;this.selected=id;this.$('[data-name]').textContent=item.label;this.$('code').textContent=item.content||'';this.$('[data-size]').textContent=`${(item.content||'').split('\n').length} lines`;this.draw();this.emit('file-select',{id:item.id,label:item.label});}
 key(e){const node=e.target.closest('[data-id]');if(!node)return;const list=this.flatten(),index=list.findIndex(n=>n.id===node.dataset.id),item=list[index];let next;if(e.key==='ArrowDown')next=list[Math.min(index+1,list.length-1)]?.id;else if(e.key==='ArrowUp')next=list[Math.max(0,index-1)]?.id;else if(e.key==='Home')next=list[0]?.id;else if(e.key==='End')next=list.at(-1)?.id;else if(e.key==='ArrowRight'&&item.children){if(!this.opened.has(item.id)){this.opened.add(item.id);this.draw();next=item.id;}else next=item.children[0]?.id;}else if(e.key==='ArrowLeft'){if(item.children&&this.opened.has(item.id)){this.opened.delete(item.id);this.draw();next=item.id;}else next=item.parent;}else if(e.key==='Enter'||e.key===' '){e.preventDefault();this.activate(item.id);next=item.id;}else return;e.preventDefault();if(next)this.focus(next);}
}
